export const financeOwner='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
export function savedAccountRow(){return{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',owner_id:financeOwner,household_id:null,visibility:'private',section:'Finances',item_type:'provider_bank_account',origin:'plaid_readonly',deleted_at:null,created_at:'2026-11-07T18:00:00Z',payload:{provider:'plaid',institution:'Chase',connectionId:'cccccccc-cccc-4ccc-8ccc-cccccccccccc',sourceId:'FICTIONAL_ACCOUNT_ID',fictional:false,content:{currency:'USD',name:'Fictional checking <script>',type:'depository',subtype:'checking',currentMinor:123456,availableMinor:100001,balanceFreshness:'provider-cached'}}};}
export function savedTransactionRows(count=25){return Array.from({length:count},(_,i)=>{const account=savedAccountRow();return{...account,id:'eeeeeeee-eeee-4eee-8eee-'+String(i+1).padStart(12,'0'),item_type:'provider_bank_transaction',payload:{...account.payload,sourceId:'FICTIONAL_TRANSACTION_'+i,content:{currency:'USD',accountId:'FICTIONAL_ACCOUNT_ID',date:new Date(Date.parse('2026-11-14T00:00:00Z')-i*86400000).toISOString().slice(0,10),name:'Fictional transaction '+(i+1),merchant:'Fictional merchant <script>',amountMinor:i%2?-1234:1234,pending:i===0,pendingTransactionId:null}}};});}
